def transform_v16(grid):
    rows, cols = len(grid), len(grid[0])

    # Find bounding box of 9s
    min_r, max_r = rows, -1
    min_c, max_c = cols, -1

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 9:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    # Output: 9 inside bounding box, 8 outside, keep original pattern elsewhere
    result = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if min_r <= r <= max_r and min_c <= c <= max_c:
                result[r][c] = 9
            elif grid[r][c] != 9:  # Keep original except 9 positions which are already handled
